CREATE TABLE IF NOT EXISTS backup_destinations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,type ENUM('local','sftp','s3') NOT NULL,config_ciphertext TEXT NOT NULL,retention_days SMALLINT UNSIGNED NOT NULL DEFAULT 30,active BOOLEAN NOT NULL DEFAULT TRUE,last_backup_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,UNIQUE(name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS backup_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,destination_id BIGINT UNSIGNED NOT NULL,job_id CHAR(32) NULL,status ENUM('queued','running','completed','failed') NOT NULL DEFAULT 'queued',filename VARCHAR(255) NULL,size_bytes BIGINT UNSIGNED NULL,checksum_sha256 CHAR(64) NULL,error_message TEXT NULL,requested_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,started_at DATETIME NULL,completed_at DATETIME NULL,FOREIGN KEY(destination_id) REFERENCES backup_destinations(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL,FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,created_at)) ENGINE=InnoDB;
